"""Focused editorial hubs and supporting pages with page-specific SEO."""
from seo import ORIGIN, SERIES, SEASON, UPDATED, breadcrumbs, page_schema
from released_guides import internal, external, esc, BROADCAST_GUIDE

TRT='https://www.trt1.com.tr/diziler/mehmed-fetihler-sultani'
NUMBER_GUIDE='/guides/mehmed-season-4-episode-numbers/'
STORY='/guides/mehmed-season-4-story-so-far/'


def edition_hub(lang):
    return SEASON+lang.lower()+'-subtitles/'


def render_pages(episodes, route):
    pages={}
    def add(url,title,description,h1,deck,body,kind='WebPage',extra=None):
        trail=[('Episode Journal','/')]
        if url.startswith(SERIES):
            if url!=SERIES:trail.append(('Sultan Fatih',SERIES))
            if url.startswith(SEASON) and url!=SEASON:trail.append(('Season 4',SEASON))
        trail.append((h1,url))
        schema=[page_schema(title,description,url,kind),breadcrumbs(trail)]
        schema.extend(extra or [])
        pages[url]=(title,description,h1,deck,body,schema)
    alias_rows=''.join(f'<tr><th scope="row">Season 4 · Episode {e["s"]}</th><td>Original Episode {e["n"]} / Bölüm {e["n"]}</td><td>{internal(route(e["n"],"Urdu"),"Urdu guide")}{internal(route(e["n"],"English"),"English guide")}</td></tr>' for e in reversed(episodes))
    add(SERIES,'Sultan Muhammad Fateh: Seasons, Episodes & Subtitle Guides',
        'Explore Mehmed Fetihler Sultani, also known as Sultan Muhammad Fateh: Season 4 release dates, episode numbering, and Urdu and English subtitle guides.',
        'Sultan Muhammad Fateh','Mehmed: Fetihler Sultanı — release dates and subtitle guides.',f'''
        <p>Mehmed: Fetihler Sultanı follows Sultan Mehmed II in a Turkish historical drama broadcast by TRT 1. The same series is commonly searched as Sultan Muhammad Fateh, Sultan Mehmed Fateh and Sultan Fatih. Serkan Çayoğlu plays Mehmed in the official TRT cast listing.</p>
        <h2>Start with Season 4</h2><p>This guide currently covers Season 4, beginning at original Episode 84. Four episodes are released; the fifth is scheduled. Each episode has a separate Urdu-subtitle and English-subtitle viewing guide, with original dates, publisher verification and story sources.</p>
        <div class="support-actions">{internal(SEASON,'Season 4 episode list','episode-button primary')}{internal(BROADCAST_GUIDE,'Broadcast dates')}</div>
        <h2>Choose your subtitle edition</h2><p>Urdu subtitles and English subtitles accompany the Turkish original. Urdu dubbing is a separate spoken-audio edition and can divide broadcasts differently.</p><div class="support-actions">{internal(edition_hub('Urdu'),'Urdu subtitle guide')}{internal(edition_hub('English'),'English subtitle guide')}</div>
        <h2>Understand the episode numbers</h2><p>Season 4 Episode 1 is original Episode 84. Season 4 Episode 4 is original Episode 87. Both numbers appear together across the site so you can match provider listings without mixing in a dubbed cut.</p>{internal(NUMBER_GUIDE,'Episode numbering explained')}
        <h2>The Season 4 story</h2><p>Mehmed prepares for Rome while a border crisis, diplomatic pressure and events in Karaman threaten his plans. Our story guide introduces those stakes without claiming a complete watched recap.</p>{internal(STORY,'Read the Season 4 story guide')}
        <h2>Official series source</h2><p>TRT provides the official cast, episode pages, synopses and weekly broadcast slot. Subtitle providers are separate viewing options.</p>{external(TRT,'Visit the official TRT series page')}
        ''', 'CollectionPage', [{'@context':'https://schema.org','@type':'TVSeries','@id':ORIGIN+SERIES+'#series','name':'Mehmed: Fetihler Sultanı','alternateName':['Sultan Muhammad Fateh','Sultan Mehmed Fateh','Sultan Fatih'],'url':ORIGIN+SERIES,'sameAs':TRT,'genre':'Historical drama','actor':{'@type':'Person','name':'Serkan Çayoğlu'}}])
    add('/about/','About Episode Journal | Turkish Drama Release & Viewing Guide',
        'Meet Episode Journal, Webcraftio’s independent drama guide for episode dates, correct numbering, sourced summaries and verified subtitle viewing options.',
        'About Episode Journal','A drama guide published by Webcraftio.',f'''
        <p>Episode Journal helps viewers find the correct episode, its original broadcast date and the subtitle edition they want. This first release focuses on Sultan Muhammad Fateh Season 4.</p><h2>Who publishes this guide?</h2><p>Episode Journal is published by Webcraftio. The publisher maintains episode records, verifies released viewing options and reviews story information against linked sources.</p>{external('https://webcraftio.com/','Visit Webcraftio')}
        <h2>Our source policy</h2><p>TRT is the primary external source for broadcast information, episode identity and official story summaries. Niazi TV is used for a secondary story check and subtitle edition links. Our own calendar brings the original dates and TRT schedule references together.</p>{internal('/how-we-check/','How we verify episodes')}
        <h2>Our viewing recommendation</h2><p>Great Nation is the publisher’s preferred free platform with notifications. It appears first, followed by Makki TV, Niazi TV and Historical Point. Ad and pop-up notes reflect the publisher’s experience.</p><h2>Corrections and updates</h2><p>We keep broadcast dates, webpage posting dates and subtitle availability separate. A verification date records a check, rather than inventing the upload time. Upcoming episodes remain upcoming until the released edition is confirmed.</p><h2>Your saved preferences</h2><p>The preference form currently stores your selection and email address on your device. Episode Journal email delivery and automatic monitoring are not connected. Great Nation has its own notification options.</p><h2>Independent editorial guide</h2><p>Episode Journal does not host full episodes or represent TRT. Series imagery belongs to TRT and the respective rights holders. Story details are original editorial summaries supported by the sources on each page.</p>
        ''','AboutPage')
    add('/how-we-check/','How Episode Journal Verifies Release Dates & Subtitles',
        'Our checking process: TRT broadcast sources, publisher-verified Urdu and English releases, episode numbering, story evidence and correction rules.',
        'How we verify episodes','Broadcast sources, viewing checks and clear update dates.',f'''
        <h2>Broadcast dates and times</h2><p>TRT 1 is the primary external source for the series’ broadcast slot, official episodes and previews. Our editorial calendar links the episode records and TRT references from one page.</p>{internal(BROADCAST_GUIDE,'View our broadcast calendar')}
        <h2>Verified subtitle releases</h2><p>The publisher confirmed the Urdu and English releases of Season 4 Episodes 1–4, original Episodes 84–87, and their viewing options on 13 October 2026. Released guides show Verified. Season 4 Episode 5, original Episode 88, remains upcoming.</p><h2>What each date means</h2><dl class="support-definitions"><div><dt>Original broadcast date</dt><dd>The date recorded for the Turkish television transmission.</dd></div><div><dt>TRT webpage date</dt><dd>The posting or update timestamp on an official webpage. It can differ from the broadcast date.</dd></div><div><dt>Verification date</dt><dd>The date the publisher confirmed the release and viewing options.</dd></div><div><dt>Subtitle upload time</dt><dd>The provider’s upload event. We do not infer it from a broadcast or verification date.</dd></div></dl>
        <h2>Story information</h2><p>TRT synopses are the primary story source. Niazi episode articles provide a secondary check. We distinguish spoiler-free introductions, synopsis-based plot details and complete watched recaps. Endings are added only when supported by direct episode evidence.</p><h2>Episode numbering</h2><p>Season numbers restart; original Turkish numbering continues. We display both. Dubbed editions can use different cuts, so their numbers should not be assumed to match a subtitled broadcast.</p>{internal(NUMBER_GUIDE,'Understand the two episode numbers')}
        <h2>Provider recommendations and corrections</h2><p>Great Nation is our preferred free platform with notifications. It appears before Makki TV, Niazi TV and Historical Point. Provider descriptions reflect publisher-supplied information. A later failed check should be recorded rather than silently overwriting a previous verification.</p><h2>Current update method</h2><p>Episode records and verification are maintained editorially. Automatic monitoring and Episode Journal email delivery are not connected yet.</p>{external(TRT,'TRT official series source')}
        ''')
    add(STORY,'Sultan Muhammad Fateh Season 4 Story Guide | Spoiler-Free',
        'A spoiler-free Sultan Fatih Season 4 story guide: Rome, the Karasu crisis, Ottoman–Akkoyunlu diplomacy and the princes’ roles, based on TRT synopses.',
        'Sultan Fatih Season 4 story guide','The background to Episodes 1–5, original Episodes 84–88.',f'''
        <p>Season 4 turns Mehmed’s attention toward Rome. A campaign in the west depends on what happens at the empire’s eastern frontier, where attacks and rival ambitions threaten to force a different priority.</p><h2>Rome and the eastern border</h2><p>The opening synopsis places Rome at the heart of Mehmed’s plans. The Karasu scheme introduces pressure on the Ottoman–Akkoyunlu border, connecting military preparation with the danger of another war.</p><h2>Diplomacy under pressure</h2><p>Episode 2, original Episode 85, centres on the demand for Karasu Fortress or Mustafa. Episode 3, original Episode 86, introduces the attack on Saruca and the danger to Ottoman envoys in Tabriz. These events explain why diplomatic decisions carry personal consequences.</p><h2>The princes and Karaman</h2><p>By Episode 4, original Episode 87, maintaining readiness in the east strains the treasury. Mustafa and Gedik Ahmed face danger in Karaman, while Bayezid receives a mission connected to Rome. This overview introduces the stakes without claiming how the final scenes resolve them.</p><h2>Where to start watching</h2><p>Begin at Season 4 Episode 1, original Episode 84. Choose a subtitle edition and keep that edition as you move through the season. The numbering guide helps distinguish these broadcasts from differently divided dubbed editions.</p><div class="support-actions">{internal(edition_hub('Urdu'),'Follow with Urdu subtitles')}{internal(edition_hub('English'),'Follow with English subtitles')}{internal(NUMBER_GUIDE,'Episode numbers explained')}</div><h2>Sources and editorial limits</h2><p>Original overview based on TRT’s official episode synopses and the linked episode guide sources. Reviewed 13 October 2026. This is a background guide rather than a complete recap or a historical fact-check.</p>{external(TRT+'/bolum','Read the official TRT synopses')}
        ''',extra=[{'@context':'https://schema.org','@type':'Article','headline':'Sultan Fatih Season 4 story guide','description':'A spoiler-free introduction to the season’s Roman ambition and eastern crisis.','image':ORIGIN+'/assets/frame-2.webp','datePublished':UPDATED,'dateModified':UPDATED,'inLanguage':'en','author':{'@id':ORIGIN+'/#publisher'},'publisher':{'@id':ORIGIN+'/#publisher'},'mainEntityOfPage':{'@id':ORIGIN+STORY+'#webpage'},'citation':TRT+'/bolum','about':{'@id':ORIGIN+SERIES+'#series'}}])
    add(NUMBER_GUIDE,'Sultan Fatih Season 4 Episode Numbers: 1–5 vs 84–88',
        'Match Sultan Muhammad Fateh Season 4 Episodes 1–5 with original Turkish Episodes 84–88, and learn why Urdu-dubbed episode numbers can differ.',
        'Season episode or original episode?','Both numbers refer to the same subtitled broadcast.',f'''
        <p>Season 4 Episode 4 is original Turkish Episode 87. Season 4 Episode 5 is original Episode 88. The season count restarts at one, while the Turkish broadcaster’s count continues across seasons.</p><h2>Season 4 numbering table</h2><div class="table-wrap"><table class="numbering-table"><caption>Sultan Fatih Season 4: season numbers and original Turkish numbers</caption><thead><tr><th scope="col">Season episode</th><th scope="col">Original broadcast</th><th scope="col">Subtitle guides</th></tr></thead><tbody>{alias_rows}</tbody></table></div><h2>What does Bölüm mean?</h2><p>Bölüm means episode in Turkish. A provider listing labelled 87. Bölüm belongs to the same original broadcast as Season 4 Episode 4 in this guide.</p><h2>Why can a dubbed number be different?</h2><p>Subtitles translate the on-screen dialogue while retaining the original spoken audio. Dubbing replaces the voice track and may be distributed in shorter cuts. A dubbed Episode 87 should not automatically be treated as original Turkish Episode 87.</p><h2>How to match a viewing page</h2><p>Check the series, season and original number together. Then confirm whether the page offers Urdu subtitles, English subtitles or Urdu dubbing. Our guides show both numbers above the viewing buttons.</p><div class="support-actions">{internal(SEASON,'Browse Season 4')}{internal(BROADCAST_GUIDE,'Check broadcast dates')}{external(TRT+'/bolum','TRT original episode list')}</div>
        ''')
    for lang in ['Urdu','English']:
        other='English' if lang=='Urdu' else 'Urdu'
        intro=("Follow Sultan Muhammad Fateh with Urdu captions and the original Turkish dialogue. This guide keeps the season number alongside the original broadcast number and separates the subtitled edition from Urdu dubbing." if lang=='Urdu' else "Follow Mehmed Fetihler Sultani in its original Turkish audio with English captions. Match the episode numbers before opening a provider, then continue through the English edition rather than switching to a different audio cut.")
        tip=("Choose Urdu Subtitles beside the Great Nation player. Urdu Dubbed is a different audio edition. If a search result uses a Roman Urdu series name such as Sultan Muhammad Fateh, check the original episode number as well as the language label." if lang=='Urdu' else "Choose English Subtitles on Great Nation. Providers may identify the drama by its Turkish title, Mehmed Fetihler Sultani, and use Bölüm instead of Episode. Match the original number before selecting the English edition.")
        cards=''
        for e in reversed(episodes):
            button=internal(route(e['n'],lang),f"Episode {e['s']}: {lang} subtitles")
            state='Upcoming' if e['upcoming'] else 'Verified release'
            cards+=f'<li class="edition-episode"><div><h2>Episode {e["s"]} <span>Original episode {e["n"]}</span></h2><p>{e["display"]} · {state}</p></div>{button}</li>'

        url=edition_hub(lang)
        add(url,f'Sultan Fatih Season 4 {lang} Subtitles | Episodes 1–5',
            f'Find Season 4 Episodes 1–5, original Episodes 84–88, with {lang} subtitles: release dates, verified viewing options and episode-specific guides.',
            f'Season 4 with {lang} subtitles',f'Episodes 1–5 · Original Turkish Episodes 84–88.',f'<p>{intro}</p><h2>Choose your episode</h2><ol class="edition-episodes">{cards}</ol><h2>How to choose the {lang} edition</h2><p>{tip}</p><h2>Release dates and availability</h2><p>The publisher verified the released Urdu and English editions of Episodes 1–4, original Episodes 84–87, on 13 October 2026. Episode 5, original Episode 88, remains upcoming. Broadcast dates and subtitle upload times are separate.</p><div class="support-actions">{internal(BROADCAST_GUIDE,"Original broadcast calendar")}{internal(NUMBER_GUIDE,"Episode numbering help")}{internal(edition_hub(other),f"Browse {other} subtitles")}</div>','CollectionPage')
    return pages
